def twoSumLessThanK(nums, k):
    nums.sort()
    left, right = 0, len(nums) - 1
    ans = -1
    while left < right:
        s = nums[left] + nums[right]
        if s < k:
            ans = max(ans, s)
            left += 1
        else:
            right -= 1
    return ans

def sortArrayByParity(nums):
    left, right = 0, len(nums) - 1
    while left < right:
        if nums[left] % 2 == 1 and nums[right] % 2 == 0:
            nums[left], nums[right] = nums[right], nums[left]
        if nums[left] % 2 == 0:
            left += 1
        if nums[right] % 2 == 1:
            right -= 1
    return nums

def check_parity(arr):
    evens = [x for x in arr if x % 2 == 0]
    odds = [x for x in arr if x % 2 == 1]
    result = sortArrayByParity(arr[:])
    return all(x % 2 == 0 for x in result[:len(evens)]) and all(x % 2 == 1 for x in result[len(evens):])

def reverseOnlyLetters(s):
    s = list(s)
    left, right = 0, len(s) - 1
    while left < right:
        while left < right and not s[left].isalpha():
            left += 1
        while left < right and not s[right].isalpha():
            right -= 1
        s[left], s[right] = s[right], s[left]
        left += 1
        right -= 1
    return ''.join(s)

