def trap(height):
    left, right = 0, len(height) - 1
    max_left = max_right = 0
    water = 0
    while left < right:
        if height[left] <= height[right]:
            if height[left] >= max_left:
                max_left = height[left]
            else:
                water += max_left - height[left]
            left += 1
        else:
            if height[right] >= max_right:
                max_right = height[right]
            else:
                water += max_right - height[right]
            right -= 1
    return water

def nextPermutation(nums):
    n = len(nums)
    i = n - 2
    while i >= 0 and nums[i] >= nums[i + 1]:
        i -= 1
    if i >= 0:
        j = n - 1
        while nums[j] <= nums[i]:
            j -= 1
        nums[i], nums[j] = nums[j], nums[i]
    left, right = i + 1, n - 1
    while left < right:
        nums[left], nums[right] = nums[right], nums[left]
        left += 1
        right -= 1

def findClosestElements(arr, k, x):
    left, right = 0, len(arr) - k
    while left < right:
        mid = (left + right) // 2
        if x - arr[mid] > arr[mid + k] - x:
            left = mid + 1
        else:
            right = mid
    return arr[left:left + k]

def longestMountain(arr):
    n = len(arr)
    res = 0
    i = 1
    while i < n - 1:
        if arr[i - 1] < arr[i] > arr[i + 1]:
            left, right = i - 1, i + 1
            while left > 0 and arr[left - 1] < arr[left]:
                left -= 1
            while right < n - 1 and arr[right] > arr[right + 1]:
                right += 1
            res = max(res, right - left + 1)
            i = right
        else:
            i += 1
    return res

def pushDominoes(dominoes):
    dominoes = 'L' + dominoes + 'R'
    result = []
    left = 0
    for right in range(1, len(dominoes)):
        if dominoes[right] == '.':
            continue
        span = right - left - 1
        if left > 0:
            result.append(dominoes[left])
        if dominoes[left] == dominoes[right]:
            result.extend([dominoes[left]] * span)
        elif dominoes[left] == 'L' and dominoes[right] == 'R':
            result.extend(['.'] * span)
        else:  # R...L
            result.extend(['R'] * (span // 2))
            if span % 2:
                result.append('.')
            result.extend(['L'] * (span // 2))
        left = right
    return ''.join(result)

from collections import Counter

def checkInclusion(s1, s2):
    if len(s1) > len(s2):
        return False
    need = Counter(s1)
    window = Counter(s2[:len(s1)])
    if window == need:
        return True
    for i in range(len(s1), len(s2)):
        window[s2[i]] += 1
        old = s2[i - len(s1)]
        window[old] -= 1
        if window[old] == 0:
            del window[old]
        if window == need:
            return True
    return False

def numSubarraysWithSum(nums, goal):
    def atMost(k):
        if k < 0:
            return 0
        left = count = curr = 0
        for right in range(len(nums)):
            curr += nums[right]
            while curr > k:
                curr -= nums[left]
                left += 1
            count += right - left + 1
        return count
    return atMost(goal) - atMost(goal - 1)

def numberOfSubarrays(nums, k):
    def atMost(k):
        left = count = odds = 0
        for right in range(len(nums)):
            if nums[right] % 2 == 1:
                odds += 1
            while odds > k:
                if nums[left] % 2 == 1:
                    odds -= 1
                left += 1
            count += right - left + 1
        return count
    return atMost(k) - atMost(k - 1)

def maxTurbulenceSize(arr):
    n = len(arr)
    res = 1
    left = 0
    for right in range(1, n):
        c = (arr[right] > arr[right-1]) - (arr[right] < arr[right-1])
        if c == 0:
            left = right
        elif right > 1:
            prev = (arr[right-1] > arr[right-2]) - (arr[right-1] < arr[right-2])
            if c == prev:
                left = right - 1
        res = max(res, right - left + 1)
    return res

def carFleet(target, position, speed):
    pairs = sorted(zip(position, speed), reverse=True)
    stack = []
    for pos, spd in pairs:
        time = (target - pos) / spd
        if not stack or time > stack[-1]:
            stack.append(time)
    return len(stack)

def reverseWords(s):
    words = s.split()
    left, right = 0, len(words) - 1
    while left < right:
        words[left], words[right] = words[right], words[left]
        left += 1
        right -= 1
    return ' '.join(words)

def compress(chars):
    write = 0
    left = 0
    while left < len(chars):
        right = left
        while right < len(chars) and chars[right] == chars[left]:
            right += 1
        count = right - left
        chars[write] = chars[left]
        write += 1
        if count > 1:
            for c in str(count):
                chars[write] = c
                write += 1
        left = right
    return write

import math

def judgeSquareSum(c):
    left, right = 0, int(math.isqrt(c))
    while left <= right:
        s = left * left + right * right
        if s == c:
            return True
        elif s < c:
            left += 1
        else:
            right -= 1
    return False

def trapStack(height):
    stack = []          # indices, heights decreasing
    water = 0
    for i, h in enumerate(height):
        while stack and height[stack[-1]] < h:
            floor = height[stack.pop()]
            if not stack:
                break   # no left wall, so nothing is bounded
            width = i - stack[-1] - 1
            bounded = min(height[stack[-1]], h) - floor
            water += width * bounded
        stack.append(i)
    return water

from collections import defaultdict

def subarraysWithKDistinct(nums, k):
    def at_most_k(k):
        count = defaultdict(int)
        left = result = 0
        for right in range(len(nums)):
            count[nums[right]] += 1
            while len(count) > k:
                count[nums[left]] -= 1
                if count[nums[left]] == 0:
                    del count[nums[left]]
                left += 1
            result += right - left + 1
        return result

    return at_most_k(k) - at_most_k(k - 1)

def findTheLongestSubstring(s):
    vowel_index = {'a': 0, 'e': 1, 'i': 2, 'o': 3, 'u': 4}
    seen = {0: -1}  # bitmask -> first index
    state = 0
    result = 0
    for i, ch in enumerate(s):
        if ch in vowel_index:
            state ^= (1 << vowel_index[ch])
        if state in seen:
            result = max(result, i - seen[state])
        else:
            seen[state] = i
    return result

def maxScore(cardPoints, k):
    n = len(cardPoints)
    window = n - k  # size of the subarray we want to minimize
    if window == 0:
        return sum(cardPoints)

    total = sum(cardPoints)
    # find minimum sum subarray of length window
    curr_sum = sum(cardPoints[:window])
    min_sum = curr_sum

    for i in range(window, n):
        curr_sum += cardPoints[i] - cardPoints[i - window]
        min_sum = min(min_sum, curr_sum)

    return total - min_sum

def minOperations(nums, x):
    target = sum(nums) - x
    if target < 0:
        return -1
    if target == 0:
        return len(nums)

    max_len = -1
    curr_sum = 0
    left = 0

    for right in range(len(nums)):
        curr_sum += nums[right]
        while curr_sum > target and left <= right:
            curr_sum -= nums[left]
            left += 1
        if curr_sum == target:
            max_len = max(max_len, right - left + 1)

    return len(nums) - max_len if max_len != -1 else -1

from collections import deque

def maxSlidingWindow(nums, k):
    dq = deque()  # indices, decreasing by value
    result = []
    for i, num in enumerate(nums):
        while dq and dq[0] < i - k + 1:
            dq.popleft()
        while dq and nums[dq[-1]] < num:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            result.append(nums[dq[0]])
    return result

def minWindowSubsequence(s1, s2):
    best = ""
    i = 0
    while i < len(s1):
        j = 0
        while i < len(s1) and j < len(s2):
            if s1[i] == s2[j]:
                j += 1
            i += 1
        if j < len(s2):
            break
        end = i
        j -= 1
        i -= 1
        while j >= 0:
            if s1[i] == s2[j]:
                j -= 1
            i -= 1
        i += 1
        window = s1[i:end]
        if not best or len(window) < len(best):
            best = window
        i += 1
    return best

def reversePairs(nums):
    def mergeSort(arr):
        if len(arr) <= 1:
            return arr, 0
        mid = len(arr) // 2
        left, lc = mergeSort(arr[:mid])
        right, rc = mergeSort(arr[mid:])
        count = lc + rc
        j = 0
        for val in left:
            while j < len(right) and val > 2 * right[j]:
                j += 1
            count += j
        merged, i, k = [], 0, 0
        while i < len(left) and k < len(right):
            if left[i] <= right[k]:
                merged.append(left[i]); i += 1
            else:
                merged.append(right[k]); k += 1
        merged.extend(left[i:])
        merged.extend(right[k:])
        return merged, count
    _, total = mergeSort(nums)
    return total

from bisect import bisect_left

def minOperations(target, arr):
    pos = {v: i for i, v in enumerate(target)}
    filtered = [pos[x] for x in arr if x in pos]
    tails = []
    for x in filtered:
        idx = bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(target) - len(tails)

def minKBitFlips(nums, k):
    n = len(nums)
    flip = [0] * n
    flipped = 0
    res = 0
    for i in range(n):
        if i >= k:
            flipped ^= flip[i - k]
        if nums[i] ^ flipped == 0:
            if i + k > n:
                return -1
            flip[i] = 1
            flipped ^= 1
            res += 1
    return res

def countSubarrays(nums, minK, maxK):
    res = 0
    bad = min_pos = max_pos = -1
    for i, x in enumerate(nums):
        if x < minK or x > maxK:
            bad = i
        if x == minK:
            min_pos = i
        if x == maxK:
            max_pos = i
        res += max(0, min(min_pos, max_pos) - bad)
    return res

def minOperations(nums):
    n = len(nums)
    unique = sorted(set(nums))
    res = n
    j = 0
    for i, x in enumerate(unique):
        while j < len(unique) and unique[j] < x + n:
            j += 1
        res = min(res, n - (j - i))
    return res

def lastSubstring(s):
    i, j, k = 0, 1, 0
    n = len(s)
    while j + k < n:
        if s[i + k] == s[j + k]:
            k += 1
        elif s[i + k] > s[j + k]:
            j = j + k + 1
            k = 0
        else:
            i = i + k + 1
            k = 0
            if i >= j:
                j = i + 1
    return s[i:]
